const kind = (d.kind === 'api-mapping') ? 'api-mapping' : 'schema-mapping';
const allowed = (kind === 'api-mapping') ? VARS_API : VARS_SCHEMA;
const required = (kind === 'api-mapping') ? [] : REQUIRED_SCHEMA;

const fieldErrors = {};
const name = String(d.name || '').trim();
