        var st = header ? String(protoAttr(header.attrs, 'status')).toLowerCase() : '';
        var metadata = protoFirstBlock(rec, 'metadata');
        var sets = protoFindBlocks(headerXml, 'setSpec').map(function (b) { return protoDecodeXml(b.inner.replace(/<[^>]*>/g, '')).trim(); });
        out.records.push({
            identifier: protoTagText(headerXml, 'identifier'),
            datestamp: protoTagText(headerXml, 'datestamp'),
            setSpec: sets,
            deleted: st === 'deleted',
            metadataXml: metadata ? metadata.inner : '',
            recordXml: blocks[i].whole
        });
        if (st === 'deleted') out.deleted++;
    }
    var tokenBlock = protoFirstBlock(xml, 'resumptionToken') || protoSelfClosing(xml, 'resumptionToken');
    if (tokenBlock) {
        out.token = protoDecodeXml(String(tokenBlock.inner || '').replace(/<[^>]*>/g, '')).trim();
        out.tokenAttrs = {
            cursor: protoAttr(tokenBlock.attrs, 'cursor'),
            completeListSize: protoAttr(tokenBlock.attrs, 'completeListSize'),
            expirationDate: protoAttr(tokenBlock.attrs, 'expirationDate')
        };
    }
    out.ok = true;
    return out;
}

// Flattens an OAI record for the asset builder while keeping the raw XML.
function oaiEntry(rec, prefix, endpoint) {
    var meta = rec.metadataXml || '';
    return {
        identifier: rec.identifier,
        title: protoTagText(meta, 'title') || rec.identifier,
        type: protoTagText(meta, 'type') || '',
        datestamp: rec.datestamp,
        setSpec: rec.setSpec.join(' '),
        metadataPrefix: prefix,
        sourceEndpoint: endpoint,
        description: protoTagText(meta, 'description'),
        publisher: protoTagText(meta, 'publisher'),
        __rawMetadata: rec.recordXml
    };
}

function sparqlBindingValue(b) {
    if (!b || typeof b !== 'object') return '';
    if (b.type === 'bnode') return '_:' + (b.value || '');
    return b.value === undefined ? '' : String(b.value);
}
function sparqlEntries(json, q) {
    var vars = (json.head && Array.isArray(json.head.vars)) ? json.head.vars : [];
    var bindings = (json.results && Array.isArray(json.results.bindings)) ? json.results.bindings : [];
    var idVar = q.idVar || vars[0] || '';
    var entries = [];
    var rejected = [];
    for (var i = 0; i < bindings.length; i++) {
        var row = bindings[i];
        var flat = {};
        for (var v = 0; v < vars.length; v++) {
            var name = vars[v];
            var cell = row[name];
            flat[name] = sparqlBindingValue(cell);
            if (cell && cell.datatype) flat[name + '__datatype'] = cell.datatype;
            if (cell && cell['xml:lang']) flat[name + '__lang'] = cell['xml:lang'];
            if (cell && cell.type) flat[name + '__type'] = cell.type;
        }
        var id = idVar ? flat[idVar] : '';
        if (!id) { rejected.push({ index: i, reason: 'no value for identifier variable ' + (idVar || '(none configured)') }); continue; }
        entries.push({
            identifier: id,
            title: (q.nameVar && flat[q.nameVar]) || id,
            type: (q.typeVar && flat[q.typeVar]) || '',
            bindings: flat,
            __rawMetadata: JSON.stringify(row)
        });
    }
    return { entries: entries, rejected: rejected, vars: vars, bindingCount: bindings.length };
}

// Protocol entries reach the asset builder through the existing sourceData contract.
function applyEntries(cat, entries, fields) {
    var existing = (cat.sourceData && Array.isArray(cat.sourceData.records)) ? cat.sourceData.records : [];
    cat.sourceData = { records: existing.concat(entries) };
    cat.responseRootPath = 'records';
    cat.responseAssetIdField = fields.id;
    cat.responseAssetNameField = fields.name;
    cat.responseAssetTypeField = fields.type;
    cat.strictAssetValidation = false;
}

// Processes one OAI-PMH page and, when a resumption token is returned, appends
// the next page to the live fetch queue.
function handleOaiPage(c) {
    var oaiCfg = (c.current.oai && c.current.oai.config) || {};
    var parsed = oaiParse(c.rawStr);
    c.ev.pages = (c.ev.pages || 0) + 1;

    if (!parsed.ok && parsed.errorCode) {
        var oaiCode = parsed.errorCode === 'badResumptionToken' ? 'OAI_BAD_RESUMPTION_TOKEN' : 'OAI_PROTOCOL_ERROR';
        var oaiLevel = parsed.errorCode === 'noRecordsMatch' ? 'warn' : 'error';
        markCatalogueFailure(c.cid, createHarvestError({ stage:'protocol', step:'oai', code:oaiCode, level:oaiLevel, catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'OAI-PMH error ' + parsed.errorCode + ' from ' + c.ep + ': ' + parsed.errorMessage, detail:{ oaiErrorCode: parsed.errorCode, page: c.ev.pages } }), oaiCode);
        if (oaiLevel === 'error') _rd.counters.parseErrors++;
        c.ev.errors.push({ code: oaiCode, oaiErrorCode: parsed.errorCode, message: parsed.errorMessage });
        return;
    }
    if (!parsed.ok) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'oai', code:'OAI_INVALID_RESPONSE', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Response from ' + c.ep + ' is not a valid OAI-PMH document: ' + (parsed.errorMessage || 'unrecognised payload') + '.', detail:{ contentType: c.contentType, page: c.ev.pages } }), 'OAI_INVALID_RESPONSE');
        _rd.counters.parseErrors++;
        c.ev.errors.push({ code: 'OAI_INVALID_RESPONSE', message: parsed.errorMessage });
        return;
    }

    var live = [];
    for (var r = 0; r < parsed.records.length; r++) {
        if (parsed.records[r].deleted) continue;
        live.push(oaiEntry(parsed.records[r], oaiCfg.metadataPrefix || '', c.current.oai.base));
    }
    c.ev.remoteRecords = (c.ev.remoteRecords || 0) + parsed.records.length;
    c.ev.deletedRecords = (c.ev.deletedRecords || 0) + parsed.deleted;
    if (parsed.tokenAttrs.cursor) c.ev.cursor = parsed.tokenAttrs.cursor;
    if (parsed.tokenAttrs.completeListSize) c.ev.completeListSize = parsed.tokenAttrs.completeListSize;
    if (parsed.tokenAttrs.expirationDate) c.ev.expirationDate = parsed.tokenAttrs.expirationDate;

    applyEntries(c.cat, live, { id: 'identifier', name: 'title', type: 'type' });
    c.cat.protocolProvenance = { protocol: 'oai-pmh', endpoint: c.current.oai.base, metadataPrefix: oaiCfg.metadataPrefix || '', setSpec: oaiCfg.setSpec || '' };
    if (_rd.catalogueStatus[c.cid] !== 'failed') _rd.catalogueStatus[c.cid] = 'ok';
    _rd.logs.push({ assetId:'', level:'info', step:'oai', code:'OAI_PAGE_OK', message:'OAI-PMH page ' + c.ev.pages + ' for ' + (c.cname || c.cid) + ': ' + parsed.records.length + ' record(s), ' + parsed.deleted + ' deleted.', catalogue:c.cname, timestamp:_nowISO() });
    if (parsed.deleted > 0) {
        _rd.logs.push({ assetId:'', level:'warn', step:'oai', code:'OAI_RECORD_DELETED', message:parsed.deleted + ' deleted OAI record(s) on page ' + c.ev.pages + ' were not imported.', catalogue:c.cname, timestamp:_nowISO() });
    }

    var tok = parsed.token;
    if (!tok) return;
    var seen = (c.current.oai && c.current.oai.seenTokens) || [];
    if (oaiCfg.resumptionTokenEnabled === false) {
        c.ev.partial = true;
        c.ev.partialReason = 'OAI_RESUMPTION_DISABLED';
        markCatalogueFailure(c.cid, createHarvestError({ stage:'protocol', step:'oai', code:'OAI_RESUMPTION_DISABLED', level:'warn', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'A resumption token was returned but pagination is disabled for ' + (c.cname || c.cid) + '; the harvest is partial.', detail:{ page: c.ev.pages } }), 'OAI_RESUMPTION_DISABLED');
        c.ev.errors.push({ code: 'OAI_RESUMPTION_DISABLED', message: 'pagination disabled' });
        return;
    }
    if (seen.indexOf(tok) >= 0) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'protocol', step:'oai', code:'OAI_RESUMPTION_TOKEN_LOOP', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'OAI-PMH resumption token repeated for ' + (c.cname || c.cid) + '; pagination stopped to avoid a loop.', detail:{ page: c.ev.pages } }), 'OAI_RESUMPTION_TOKEN_LOOP');
        c.ev.errors.push({ code: 'OAI_RESUMPTION_TOKEN_LOOP', message: 'repeated resumption token' });
        return;
    }
    if (c.ev.pages >= (oaiCfg.maxPages || 50)) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'protocol', step:'oai', code:'OAI_MAX_PAGES_REACHED', level:'warn', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'OAI-PMH page limit (' + (oaiCfg.maxPages || 50) + ') reached for ' + (c.cname || c.cid) + '; the harvest is partial.', detail:{ page: c.ev.pages } }), 'OAI_MAX_PAGES_REACHED');
        c.ev.errors.push({ code: 'OAI_MAX_PAGES_REACHED', message: 'page limit reached' });
        c.ev.partial = true;
        c.ev.partialReason = 'OAI_MAX_PAGES_REACHED';
        return;
    }
    c.ev.resumptionTokensFollowed = true;
    c.ev.currentToken = tok.length > 24 ? (tok.slice(0, 24) + '...') : tok;
    c.queue.push({
        step: 'data', protocol: 'oai-pmh', catIdx: c.current.catIdx, catName: c.current.catName,
        url: protoOaiUrl(c.current.oai.base, { resumptionToken: tok }),
        method: 'GET', body: '', hdrs: c.current.hdrs, requestedMime: c.current.requestedMime,
        oai: { base: c.current.oai.base, page: (c.current.oai.page || 1) + 1, seenTokens: seen.concat([tok]), config: oaiCfg }
    });
}

// Processes a query-interface (SPARQL or custom query) result set.
function handleQueryResult(c) {
    var q = c.current.query;
    var mode = q.resultMode || 'sparql-select';
    c.ev.pages = (c.ev.pages || 0) + 1;

    if (protoRdfMime(c.contentType) || mode === 'rdf') {
        // CONSTRUCT / DESCRIBE results go through the RDF/DCAT parser.
        c.cat.sourceData = { __rdfRaw: c.rawStr, __rdfContentType: c.contentType || q.resultMime || '' };
        c.cat.sourceContentType = c.contentType;
        c.cat.protocolProvenance = { protocol: 'query-interface', endpoint: q.endpoint, queryLanguage: q.language, queryMethod: q.method, query: q.text };
        if (_rd.catalogueStatus[c.cid] !== 'failed') _rd.catalogueStatus[c.cid] = 'ok';
        _rd.logs.push({ assetId:'', level:'info', step:'query', code:'QUERY_RDF_OK', message:'Query returned RDF (' + c.contentType + ') for ' + (c.cname || c.cid) + '.', catalogue:c.cname, timestamp:_nowISO() });
        return;
    }
    if (!c.parsedJson) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'query', code:'QUERY_RESULT_INVALID', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Query result from ' + c.ep + ' is neither valid JSON nor RDF (content type ' + (c.contentType || 'unknown') + ').', detail:{ contentType: c.contentType } }), 'QUERY_RESULT_INVALID');
        _rd.counters.parseErrors++;
        c.ev.errors.push({ code: 'QUERY_RESULT_INVALID', message: 'unparseable query result' });
        return;
    }
    if (mode === 'custom-json') {
        var root = q.rootPath ? resolvePath(c.data, q.rootPath) : c.data;
        if (!root) {
            markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'query', code:'QUERY_RESULT_INVALID', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Query result from ' + c.ep + ' has no data at the configured result root ' + (q.rootPath || '(root)') + '.', detail:{ rootPath: q.rootPath } }), 'QUERY_RESULT_INVALID');
            _rd.counters.parseErrors++;
            return;
        }
        c.cat.sourceData = c.data;
        c.cat.responseRootPath = q.rootPath || c.cat.responseRootPath || '';
        c.cat.protocolProvenance = { protocol: 'query-interface', endpoint: q.endpoint, queryLanguage: q.language, queryMethod: q.method, query: q.text };
        c.ev.resultCount = Array.isArray(root) ? root.length : 1;
        if (_rd.catalogueStatus[c.cid] !== 'failed') _rd.catalogueStatus[c.cid] = 'ok';
        return;
    }
    if (c.data && typeof c.data.boolean === 'boolean') {
        // ASK is recorded as query evidence and never produces assets.
        c.ev.askResult = c.data.boolean;
        c.ev.resultCount = 0;
        c.cat.sourceData = { records: [] };
        c.cat.responseRootPath = 'records';
        c.cat.protocolProvenance = { protocol: 'query-interface', endpoint: q.endpoint, queryLanguage: q.language, queryMethod: q.method, query: q.text };
        if (_rd.catalogueStatus[c.cid] !== 'failed') _rd.catalogueStatus[c.cid] = 'ok';
        _rd.logs.push({ assetId:'', level:'info', step:'query', code:'SPARQL_ASK_OK', message:'SPARQL ASK returned ' + c.data.boolean + ' for ' + (c.cname || c.cid) + '; ASK queries do not create assets.', catalogue:c.cname, timestamp:_nowISO() });
        return;
    }
    if (c.data && c.data.head && c.data.results && Array.isArray(c.data.results.bindings)) {
        var sel = sparqlEntries(c.data, q);
        c.ev.bindingCount = (c.ev.bindingCount || 0) + sel.bindingCount;
        c.ev.variables = sel.vars;
        c.ev.resultCount = (c.ev.resultCount || 0) + sel.entries.length;
        for (var rj = 0; rj < sel.rejected.length; rj++) {
            _rd.errors.push(createHarvestError({ stage:'entry', step:'query', code:'QUERY_RESULT_INVALID', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'SPARQL binding ' + sel.rejected[rj].index + ' skipped: ' + sel.rejected[rj].reason + '.', detail:{} }));
            _rd.counters.entryErrors++;
        }
        applyEntries(c.cat, sel.entries, { id: 'identifier', name: 'title', type: 'type' });
        c.cat.protocolProvenance = { protocol: 'query-interface', endpoint: q.endpoint, queryLanguage: q.language, queryMethod: q.method, query: q.text };
        if (_rd.catalogueStatus[c.cid] !== 'failed') _rd.catalogueStatus[c.cid] = 'ok';
        _rd.logs.push({ assetId:'', level:'info', step:'query', code:'SPARQL_SELECT_OK', message:'SPARQL SELECT returned ' + sel.bindingCount + ' binding(s); ' + sel.entries.length + ' asset(s) derived for ' + (c.cname || c.cid) + '.', catalogue:c.cname, timestamp:_nowISO() });
        return;
    }
    markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'query', code:'SPARQL_RESULT_INVALID', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Query result from ' + c.ep + ' is JSON but not a SPARQL result set: no head/results.bindings and no boolean.', detail:{ contentType: c.contentType } }), 'SPARQL_RESULT_INVALID');
    _rd.counters.parseErrors++;
    c.ev.errors.push({ code: 'SPARQL_RESULT_INVALID', message: 'not a SPARQL result set' });
}

// DCAT must be genuine RDF. The acceptance rule is shared verbatim with Test
// Connection, so a response accepted there cannot be rejected here. A generic
// content type such as text/plain is accepted only when the body really parses.
function handleDcatResult(c) {
    c.ev.pages = (c.ev.pages || 0) + 1;
    var configuredMime = c.cat.mimeType || c.cat.contentNegotiation || '';
    var verdict = rdfAccept(c.rawStr, c.contentType, c.current.requestedMime, configuredMime);

    if (!verdict.ok) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'dcat', code:'DCAT_RESPONSE_INVALID', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Response from ' + c.ep + ' is not recognisable RDF/DCAT: ' + verdict.reason + ' (content type ' + (c.contentType || 'unknown') + ').', detail:{ contentType: c.contentType || '', requestedMime: c.current.requestedMime || '' } }), 'DCAT_RESPONSE_INVALID');
        _rd.counters.parseErrors++;
        c.ev.errors.push({ code: 'DCAT_RESPONSE_INVALID', message: verdict.reason });
        return;
    }

    // The canonical format detected here is what the NF-6 transform pipeline
    // parses, so text/plain never reaches the RDF parser as the source format.
    c.cat.sourceData = {
        __rdfRaw: c.rawStr,
        __rdfContentType: verdict.type,
        __rdfSubject: verdict.subject || '',
        __rdfTitle: verdict.title || ''
    };
    c.cat.sourceContentType = verdict.type;
    c.cat.protocolProvenance = {
        protocol: 'dcat',
        endpoint: c.current.url,
        mimeType: verdict.type,
        responseContentType: c.contentType || '',
        statements: verdict.statements
    };
    c.ev.remoteRecords = (c.ev.remoteRecords || 0) + 1;
    c.ev.rdfFormat = verdict.type;
    c.ev.rdfStatements = verdict.statements;
    _rd.catalogueStatus[c.cid] = 'ok';
    _rd.logs.push({ assetId:'', level:'info', step:'dcat', code:'DCAT_OK', message:'Fetched DCAT data for ' + (c.cname || c.cid) + ': ' + verdict.statements + ' statement(s) parsed as ' + verdict.type + ' (server sent ' + (c.contentType || 'no content type') + ').', catalogue:c.cname, timestamp:_nowISO() });
}

// Plain REST/JSON query interfaces: the historical FACIS behaviour.
function handleRestResult(c) {
    var looksHtml = /^\s*<(!doctype|html)[\s>]/i.test(c.rawStr) || /text\/html/i.test(c.contentType);
    var isEmpty = (c.data === null || c.data === undefined || c.data === '' || (typeof c.raw === 'string' && !c.raw.trim()));
    var looksJson = (typeof c.raw === 'string') && (/json/i.test(c.contentType) || looksLikeJsonText(c.raw));

    if (looksHtml) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'parse', code:'unsupported_content_type', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Endpoint ' + c.ep + ' returned HTML, not machine-readable data, for catalogue ' + (c.cname || c.cid) + '.', detail:{ contentType: c.contentType } }), 'unsupported_content_type');
        _rd.counters.parseErrors++;
        return;
    }
    if (isEmpty) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'parse', code:'empty_response', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Endpoint ' + c.ep + ' returned an empty response for catalogue ' + (c.cname || c.cid) + '.', detail:{ contentType: c.contentType } }), 'empty_response');
        _rd.counters.parseErrors++;
        return;
    }
    if (looksJson && !c.parsedJson) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'parse', code:'unparseable_response', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Response from ' + c.ep + ' for catalogue ' + (c.cname || c.cid) + ' is not valid JSON.', detail:{ contentType: c.contentType } }), 'unparseable_response');
        _rd.counters.parseErrors++;
        return;
    }
    if (!c.parsedJson && !_isRdfType(c.contentType)) {
        markCatalogueFailure(c.cid, createHarvestError({ stage:'parse', step:'parse', code:'unsupported_content_type', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Response from ' + c.ep + ' for catalogue ' + (c.cname || c.cid) + ' is neither JSON nor a recognised RDF media type.', detail:{ contentType: c.contentType } }), 'unsupported_content_type');
        _rd.counters.parseErrors++;
        return;
    }
    c.cat.sourceData = c.parsedJson ? c.data : { __rdfRaw: c.rawStr, __rdfContentType: c.contentType || c.current.requestedMime || '' };
    c.cat.sourceContentType = c.contentType || c.current.requestedMime || '';
    var restMapping = c.ev.responseMapping || {
        rootPath: c.cat.responseRootPath || '',
        idField: c.cat.responseAssetIdField || '',
        nameField: c.cat.responseAssetNameField || '',
        typeField: c.cat.responseAssetTypeField || ''
    };
    var restRoot = restMapping.rootPath ? resolvePath(c.data, restMapping.rootPath) : c.data;
    var restCount = Array.isArray(restRoot) ? restRoot.length : (restRoot ? 1 : 0);
    c.cat.protocolProvenance = {
        protocol: 'query-interface',
        endpoint: c.current.url,
        queryLanguage: 'rest-json',
        queryMethod: c.current.method || 'GET',
        mimeType: c.current.requestedMime || '',
        responseContentType: c.contentType || ''
    };
    c.ev.queryLanguage = c.ev.queryLanguage || 'rest-json';
    c.ev.queryMethod = c.ev.queryMethod || c.current.method || 'GET';
    c.ev.resultMimeType = c.ev.resultMimeType || c.current.requestedMime || '';
    c.ev.responseContentType = c.contentType || '';
    c.ev.responseMapping = restMapping;
    c.ev.resultCount = (c.ev.resultCount || 0) + restCount;
    c.ev.remoteRecords = (c.ev.remoteRecords || 0) + restCount;
    c.ev.pages = (c.ev.pages || 0) + 1;
    _rd.catalogueStatus[c.cid] = 'ok';
    _rd.logs.push({ assetId:'', level:'info', step:'fetch', code:'fetch_ok', message:'Fetched API data for ' + (c.cname || c.cid) + ' (HTTP ' + c.status + ', ' + (c.contentType || 'unknown content type') + ')', catalogue:c.cname, timestamp:_nowISO() });
}

function handleLoginStep(c) {
    if (c.parsedJson && c.data && c.status >= 200 && c.status < 300) {
        var token = resolvePath(c.data, c.current.tokenPath || 'token');
        if (token) {
            for (var j = c.idx + 1; j < c.queue.length; j++) {
                if (c.queue[j].catIdx === c.current.catIdx && c.queue[j].step === 'data') {
                    c.queue[j].hdrs['Authorization'] = (c.current.tokenPrefix || 'Bearer') + ' ' + String(token);
                    break;
                }
            }
            return;
        }
        markCatalogueFailure(c.cid, createHarvestError({ stage:'protocol', step:'login', code:'auth_no_token', catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:false, message:'Login to ' + (c.cname || c.cid) + ' returned no token; the data fetch would be unauthenticated.', detail:{ tokenPath: c.current.tokenPath || 'token' } }), 'auth_no_token');
        return;
    }
    var code = (c.status === 401 || c.status === 403) ? ('http_' + c.status) : (c.status >= 500 ? 'http_5xx' : (c.status >= 400 ? 'http_4xx' : 'ECONNREFUSED'));
    markCatalogueFailure(c.cid, createHarvestError({ stage:'transport', step:'login', code:code, catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:(c.status === 0 || c.status >= 500 || c.status === 429), message:'Login failed (HTTP ' + c.status + ') for catalogue ' + (c.cname || c.cid) + '.', detail:{ httpCode: c.status } }), code);
    _rd.counters.transportErrors++;
}

// Returns true when the HTTP exchange itself failed and no body should be parsed.
function handleTransportFailure(c) {
    if (c.status === 0 || c.status == null || c.status < 200) {
        var code = 'ECONNREFUSED';
        if (/ENOTFOUND|getaddrinfo/i.test(c.rawStr)) code = 'ENOTFOUND';
        else if (/ETIMEDOUT|ESOCKETTIMEDOUT|timed? ?out/i.test(c.rawStr)) code = 'ETIMEDOUT';
        else if (/ECONNRESET/i.test(c.rawStr)) code = 'ECONNRESET';
        else if (/self.signed|CERT_|DEPTH_ZERO|unable to verify|SSL|TLS/i.test(c.rawStr)) code = 'TLS_ERROR';
        else if (/maximum redirect|redirect/i.test(c.rawStr)) code = 'REDIRECT_LOOP';
        markCatalogueFailure(c.cid, createHarvestError({ stage:'transport', step:'fetch', code:code, catalogueId:c.cid, catalogueName:c.cname, endpoint:c.ep, assetId:null, retryable:true, message:'Could not reach ' + c.ep + ' for catalogue ' + (c.cname || c.cid) + ' (' + code + ').', detail:{ httpCode: c.status, protocol: c.protocol } }), code);
        _rd.counters.transportErrors++;
        c.ev.errors.push({ code: code, message: 'transport failure' });
